-- FAZUM PostgreSQL baseline. Additive only: MongoDB remains the live source until cutover.
-- PostgreSQL 15+ / Alembic revision: 0001
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TYPE account_status AS ENUM ('PENDING_VERIFICATION','ACTIVE','SUSPENDED','BLOCKED','DELETED');
CREATE TYPE preference_type AS ENUM ('client','worker','both');
CREATE TYPE order_status AS ENUM ('published','accepted','in_progress','completion_requested','completed','cancelled','disputed');
CREATE TYPE proposal_status AS ENUM ('pending','accepted','rejected','withdrawn');
CREATE TYPE payment_status AS ENUM ('pending','held','released','refunded','failed','cancelled');
CREATE TYPE transaction_direction AS ENUM ('IN','OUT','MOVE');
CREATE TYPE transaction_status AS ENUM ('PENDING','COMPLETED','FAILED','REVERSED');
CREATE TYPE wallet_bucket AS ENUM ('available','pending','processing');
CREATE TYPE withdrawal_status AS ENUM ('PENDING','REVIEW_REQUIRED','PROCESSING','COMPLETED','FAILED','REJECTED','CANCELLED');
CREATE TYPE case_status AS ENUM ('OPEN','UNDER_REVIEW','WAITING_CUSTOMER','WAITING_PROVIDER','RESOLVED','REJECTED','CANCELLED');
CREATE TYPE ticket_status AS ENUM ('OPEN','IN_PROGRESS','WAITING_USER','RESOLVED','CLOSED');
CREATE TYPE admin_role_key AS ENUM ('OWNER','MANAGER','SUPPORT','MAINTENANCE');
CREATE TYPE delivery_status AS ENUM ('PENDING','SENT','DELIVERED','FAILED','READ');

CREATE TABLE states (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, name text NOT NULL, uf char(2) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, state_id uuid NOT NULL REFERENCES states(id), name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(state_id,name));
CREATE TABLE neighborhoods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, city_id uuid NOT NULL REFERENCES cities(id), name text NOT NULL, kind text NOT NULL DEFAULT 'bairro', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(city_id,name));
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, name text NOT NULL UNIQUE, icon text NOT NULL, display_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subcategories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, category_id uuid NOT NULL REFERENCES categories(id), name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(category_id,name));

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, email citext UNIQUE, phone text UNIQUE, password_hash text, name text NOT NULL, initials text, bio text NOT NULL DEFAULT '', avatar_url text, city_id uuid REFERENCES cities(id), neighborhood_id uuid REFERENCES neighborhoods(id), preference preference_type NOT NULL DEFAULT 'both', rating numeric(3,2) NOT NULL DEFAULT 5 CHECK(rating BETWEEN 0 AND 5), rating_count integer NOT NULL DEFAULT 0 CHECK(rating_count>=0), jobs_done integer NOT NULL DEFAULT 0 CHECK(jobs_done>=0), verified_email boolean NOT NULL DEFAULT false, verified_phone boolean NOT NULL DEFAULT false, verified_identity boolean NOT NULL DEFAULT false, email_verified_at timestamptz, phone_verified_at timestamptz, account_status account_status NOT NULL DEFAULT 'PENDING_VERIFICATION', blocked boolean NOT NULL DEFAULT false, token_version integer NOT NULL DEFAULT 0, notification_prefs jsonb NOT NULL DEFAULT '{}'::jsonb, member_since timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(email IS NOT NULL OR phone IS NOT NULL));
CREATE INDEX users_city_status_idx ON users(city_id,account_status) WHERE deleted_at IS NULL;
CREATE TABLE auth_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL, provider_account_id text NOT NULL, provider_data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_account_id));
CREATE TABLE verification_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, user_id uuid NOT NULL REFERENCES users(id), type text NOT NULL CHECK(type IN ('email','phone','password_reset')), code_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, used_at timestamptz, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_tokens_active_idx ON verification_tokens(user_id,type,created_at DESC) WHERE used_at IS NULL;
CREATE TABLE user_blocks (user_id uuid NOT NULL REFERENCES users(id), blocked_user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,blocked_user_id), CHECK(user_id<>blocked_user_id));
CREATE TABLE security_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, user_id uuid REFERENCES users(id), kind text NOT NULL, detail text, ip inet, user_agent text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, client_id uuid NOT NULL REFERENCES users(id), worker_id uuid REFERENCES users(id), category_id uuid NOT NULL REFERENCES categories(id), subcategory_id uuid REFERENCES subcategories(id), city_id uuid NOT NULL REFERENCES cities(id), neighborhood_id uuid REFERENCES neighborhoods(id), title text NOT NULL, description text NOT NULL DEFAULT '', type text NOT NULL DEFAULT 'favor' CHECK(type IN ('favor','servico')), status order_status NOT NULL DEFAULT 'published', date_label text NOT NULL DEFAULT 'Hoje', time_label text NOT NULL DEFAULT '', budget_cents bigint NOT NULL DEFAULT 0 CHECK(budget_cents>=0), fields jsonb NOT NULL DEFAULT '{}'::jsonb, urgent boolean NOT NULL DEFAULT false, recurrence text NOT NULL DEFAULT 'none', reviewed_by_client boolean NOT NULL DEFAULT false, reviewed_by_worker boolean NOT NULL DEFAULT false, pre_dispute_status order_status, external_payment_restricted boolean NOT NULL DEFAULT false, started_at timestamptz, completed_at timestamptz, cancelled_at timestamptz, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(worker_id IS NULL OR worker_id<>client_id));
CREATE INDEX orders_browse_idx ON orders(city_id,status,created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX orders_client_idx ON orders(client_id,created_at DESC); CREATE INDEX orders_worker_idx ON orders(worker_id,created_at DESC);
CREATE TABLE order_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, storage_key text NOT NULL, display_order smallint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,display_order));
CREATE TABLE order_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), from_status order_status, to_status order_status NOT NULL, actor_user_id uuid REFERENCES users(id), actor_admin_id uuid, reason text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX order_status_history_idx ON order_status_history(order_id,created_at);
CREATE TABLE proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, order_id uuid NOT NULL REFERENCES orders(id), worker_id uuid NOT NULL REFERENCES users(id), amount_cents bigint NOT NULL CHECK(amount_cents>=0), message text NOT NULL DEFAULT '', eta text NOT NULL DEFAULT '', status proposal_status NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,worker_id));
CREATE INDEX proposals_worker_idx ON proposals(worker_id,created_at DESC);
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, order_id uuid NOT NULL REFERENCES orders(id), sender_id uuid REFERENCES users(id), sender_kind text NOT NULL CHECK(sender_kind IN ('user','system','admin')), type text NOT NULL DEFAULT 'text', text text NOT NULL DEFAULT '', image_storage_key text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_order_idx ON messages(order_id,created_at);
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, order_id uuid NOT NULL REFERENCES orders(id), from_id uuid NOT NULL REFERENCES users(id), to_id uuid NOT NULL REFERENCES users(id), stars smallint NOT NULL CHECK(stars BETWEEN 1 AND 5), comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,from_id), CHECK(from_id<>to_id));
CREATE INDEX reviews_target_idx ON reviews(to_id,created_at DESC);
CREATE TABLE favorites (user_id uuid NOT NULL REFERENCES users(id), order_id uuid NOT NULL REFERENCES orders(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,order_id));
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, reporter_id uuid NOT NULL REFERENCES users(id), target_type text NOT NULL CHECK(target_type IN ('user','order','message')), target_legacy_id text NOT NULL, reason text NOT NULL, details text NOT NULL DEFAULT '', status case_status NOT NULL DEFAULT 'OPEN', resolution text NOT NULL DEFAULT '', resolved_by_admin_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reports_target_idx ON reports(target_type,target_legacy_id); CREATE TABLE disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, order_id uuid NOT NULL REFERENCES orders(id), reporter_id uuid NOT NULL REFERENCES users(id), target_type text NOT NULL, reason text NOT NULL, description text NOT NULL DEFAULT '', status case_status NOT NULL DEFAULT 'OPEN', resolution text NOT NULL DEFAULT '', resolved_by_admin_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dispute_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dispute_id uuid NOT NULL REFERENCES disputes(id) ON DELETE CASCADE, storage_key text NOT NULL, created_by_user_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE wallets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, user_id uuid NOT NULL REFERENCES users(id), currency char(3) NOT NULL DEFAULT 'BRL', available_cents bigint NOT NULL DEFAULT 0 CHECK(available_cents>=0), pending_cents bigint NOT NULL DEFAULT 0 CHECK(pending_cents>=0), processing_cents bigint NOT NULL DEFAULT 0 CHECK(processing_cents>=0), total_received_cents bigint NOT NULL DEFAULT 0 CHECK(total_received_cents>=0), total_spent_cents bigint NOT NULL DEFAULT 0 CHECK(total_spent_cents>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,currency));
CREATE TABLE wallet_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, wallet_id uuid NOT NULL REFERENCES wallets(id), user_id uuid NOT NULL REFERENCES users(id), type text NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents>0), direction transaction_direction NOT NULL, status transaction_status NOT NULL, bucket text NOT NULL, reference_type text NOT NULL, reference_legacy_id text NOT NULL, provider text, provider_transaction_id text, idempotency_key text UNIQUE, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX wallet_transactions_user_idx ON wallet_transactions(user_id,created_at DESC);
CREATE TABLE bank_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, user_id uuid NOT NULL REFERENCES users(id), holder_name text NOT NULL, document_encrypted bytea NOT NULL, document_last4 char(4) NOT NULL, bank_code text NOT NULL, agency_encrypted bytea NOT NULL, account_number_encrypted bytea NOT NULL, account_last4 char(4) NOT NULL, account_type text NOT NULL, is_primary boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_primary_bank_account_idx ON bank_accounts(user_id) WHERE is_primary AND active AND deleted_at IS NULL;
CREATE TABLE deposits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, user_id uuid NOT NULL REFERENCES users(id), amount_cents bigint NOT NULL CHECK(amount_cents>0), method text NOT NULL, status payment_status NOT NULL DEFAULT 'pending', provider text, provider_transaction_id text, idempotency_key text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, order_id uuid NOT NULL UNIQUE REFERENCES orders(id), client_id uuid NOT NULL REFERENCES users(id), worker_id uuid NOT NULL REFERENCES users(id), gross_amount_cents bigint NOT NULL CHECK(gross_amount_cents>0), commission_amount_cents bigint NOT NULL CHECK(commission_amount_cents>=0), worker_net_amount_cents bigint NOT NULL CHECK(worker_net_amount_cents>=0), commission_percent numeric(5,2) NOT NULL, method text NOT NULL, status payment_status NOT NULL DEFAULT 'pending', provider text, provider_transaction_id text, idempotency_key text UNIQUE, client_ip inet, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(gross_amount_cents=commission_amount_cents+worker_net_amount_cents));
CREATE TABLE withdrawals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, user_id uuid NOT NULL REFERENCES users(id), amount_cents bigint NOT NULL CHECK(amount_cents>0), bank_account_id uuid REFERENCES bank_accounts(id), bank_account_snapshot jsonb NOT NULL, status withdrawal_status NOT NULL DEFAULT 'PENDING', risk_level text, risk_reasons jsonb NOT NULL DEFAULT '[]'::jsonb, provider text, provider_transaction_id text, idempotency_key text UNIQUE, reviewed_by_admin_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX withdrawals_user_idx ON withdrawals(user_id,created_at DESC);
CREATE TABLE payment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, provider text NOT NULL DEFAULT 'asaas', event_id text NOT NULL, payload jsonb NOT NULL, signature_valid boolean NOT NULL DEFAULT false, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, processing_error text, UNIQUE(provider,event_id));

CREATE TABLE admin_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, key admin_role_key NOT NULL UNIQUE, name text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE permissions (key text PRIMARY KEY, description text NOT NULL);
CREATE TABLE role_permissions (role_id uuid NOT NULL REFERENCES admin_roles(id) ON DELETE CASCADE, permission_key text NOT NULL REFERENCES permissions(key) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_key));
CREATE TABLE admin_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, email citext NOT NULL UNIQUE, password_hash text NOT NULL, name text NOT NULL, role_id uuid NOT NULL REFERENCES admin_roles(id), active boolean NOT NULL DEFAULT true, token_version integer NOT NULL DEFAULT 0, totp_secret_encrypted bytea, totp_enabled_at timestamptz, last_login_at timestamptz, last_active_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE admin_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, admin_id uuid REFERENCES admin_users(id), action text NOT NULL, resource_type text, resource_legacy_id text, reason text, result text NOT NULL DEFAULT 'SUCCESS', ip inet, user_agent text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX admin_actions_time_idx ON admin_actions(created_at DESC);
CREATE TABLE risk_flags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, user_id uuid REFERENCES users(id), kind text NOT NULL, reference_legacy_id text, level text NOT NULL CHECK(level IN ('LOW','MEDIUM','HIGH','CRITICAL')), reasons jsonb NOT NULL DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','RESOLVED','DISMISSED')), note text, resolved_by_admin_id uuid REFERENCES admin_users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE feature_flags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, key text NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT false, description text, rules jsonb NOT NULL DEFAULT '{}'::jsonb, updated_by_admin_id uuid REFERENCES admin_users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, user_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, body text NOT NULL, type text NOT NULL, order_id uuid REFERENCES orders(id), read boolean NOT NULL DEFAULT false, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_inbox_idx ON notifications(user_id,read,created_at DESC);
CREATE TABLE notification_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), notification_id uuid NOT NULL REFERENCES notifications(id) ON DELETE CASCADE, channel text NOT NULL CHECK(channel IN ('in_app','push','email','sms')), status delivery_status NOT NULL DEFAULT 'PENDING', provider_message_id text, error text, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, created_by uuid NOT NULL REFERENCES users(id), category text NOT NULL, subject text NOT NULL, description text NOT NULL, status ticket_status NOT NULL DEFAULT 'OPEN', assigned_to uuid REFERENCES admin_users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE INDEX tickets_queue_idx ON tickets(status,category,created_at DESC);
CREATE TABLE ticket_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legacy_id text UNIQUE, ticket_id uuid NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, author_kind text NOT NULL CHECK(author_kind IN ('user','admin','system')), author_user_id uuid REFERENCES users(id), author_admin_id uuid REFERENCES admin_users(id), text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_config (key text PRIMARY KEY, value jsonb NOT NULL, updated_by_admin_id uuid REFERENCES admin_users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE migration_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL, source_fingerprint text NOT NULL, status text NOT NULL CHECK(status IN ('RUNNING','VALIDATED','COMPLETED','FAILED','ROLLED_BACK')), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, details jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(source,source_fingerprint));
CREATE TABLE legacy_id_map (collection_name text NOT NULL, legacy_id text NOT NULL, postgres_table text NOT NULL, postgres_id uuid NOT NULL, migration_run_id uuid REFERENCES migration_runs(id), PRIMARY KEY(collection_name,legacy_id));

CREATE OR REPLACE FUNCTION fazum_touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION fazum_deny_admin_action_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'admin_actions is append-only'; END $$;
CREATE TRIGGER admin_actions_append_only BEFORE UPDATE OR DELETE ON admin_actions FOR EACH ROW EXECUTE FUNCTION fazum_deny_admin_action_change();
